const ERAS = [
['prehistory','旧石器时代—约前2000','史前生活、艺术与聚落','共同体如何组织起来？','农业定居带来聚落、墓葬与仪式空间。欧洲各地区的发展并不同步，巨石遗迹提供了文字之前的社会证据。','从定居社会走向更复杂的城市与政治组织。'],
['bronze','约前3000—前1100','青铜时代的宫殿与城堡','宫殿如何组织贸易和权力？','爱琴海的宫殿、城堡与墓葬记录早期复杂社会。米诺斯与迈锡尼文化有交流，也有不同的政治组织。','宫殿体系衰落以后，城邦在新的社会条件下逐渐形成。'],
['greece','约前800—前146','城邦与希腊世界','共享文化，为什么没有一个统一国家？','城邦竞争与跨地区圣地同时存在。城邦政治、海上交流与希腊化世界，为后来的地中海历史提供重要背景。','罗马逐渐把这些互相竞争的地区纳入更大的政治网络。'],
['rome','约前509—公元395','罗马共和国与帝国','辽阔领土靠什么连接？','道路、城市、法律与军队把地中海周围连接起来。边疆既是军事界线，也是贸易和人口流动的区域。','帝国重心与宗教改变；东西部的政治轨迹逐渐分化。'],
['late','约300—700','罗马的转型与延续','西部帝位消失，罗马就结束了吗？','基督教改变公共空间与权力表达。西部出现新的王国，东罗马继续存在；拉文纳留下了多次政权转换的物质证据。','东罗马延续，西欧则形成新的王权与教会关系。'],
['carolingian','约750—1000','加洛林、维京与早期王国','谁能继承罗马的帝国理想？','加洛林统治者与教会共同建构权威。800年查理曼加冕；843年帝国分割。北欧也在王权与基督教化中发生变化。','欧洲形成多个政治中心，教会、王权与城市彼此竞争。'],
['medieval','约1000—1400','教会、王国与商业城市','权力只属于国王吗？','大教堂、大学、商人城市和跨海贸易共同塑造中世纪欧洲。不同区域的王国形成与城市发展并不沿同一节奏。','城市财富与知识网络为艺术和思想的新变化提供条件。'],
['frontiers','约711—1600','伊斯兰、拜占庭与奥斯曼','欧洲的边界如何成为交流地带？','伊比利亚与东地中海同时存在战争、统治转换和文化交流。1453年君士坦丁堡陷落、1492年格拉纳达易手，是两条不同的历史线。','这些变化与文艺复兴、海上扩张同时发生，不是前后相继的单线。'],
['renaissance','约1400—1600','文艺复兴与海上扩张','城市财富如何改变世界观？','意大利城市的赞助网络与古典知识重读推动艺术变化；伊比利亚海上扩张连接全球，也带来征服、殖民与剥削。','新的知识、商业财富和宗教争论冲击既有权威。'],
['reformation','1517—1648','宗教改革与政治分裂','信仰为什么会重画政治版图？','宗教改革涉及信仰、传播与统治权。战争与谈判改变了欧洲秩序；1648年是重要节点，但不是现代国家突然诞生的一年。','王朝国家继续整合权力，商业共和国发展不同的制度。'],
['dynasties','约1600—1789','王朝、共和国与启蒙','谁拥有城市和国家的主导权？','宫廷、商人精英与帝国首都呈现不同的权力模式。宫殿和城市规划既展示审美，也组织社会等级和经济活动。','启蒙思想、财政危机与社会冲突共同通向革命时代。'],
['revolution','1789—1871','革命与民族国家','臣民如何成为公民？','法国革命、拿破仑战争与其后政治重组改变主权观念。民族主义、帝国和自由主义相互竞争，并不只有一种现代化道路。','工业化加速社会变化，国家动员能力也不断增强。'],
['industry','约1750—1914','工业化与帝国社会','工厂如何改变日常生活？','煤、铁、机器和运输网络改变劳动与城市。工业增长与全球殖民体系相互关联，财富与社会代价必须一起观察。','大众社会、技术与政治冲突进入20世纪。'],
['war','1914—1945','世界大战与现代性危机','现代社会为何走向大规模毁灭？','战争、独裁、种族迫害与大屠杀必须与现代艺术和社会实验并置理解。纪念地的参观以理解受害者和历史责任为中心。','战后重建、冷战分裂与合作机制同时展开。'],
['postwar','1945—今天','重建、分裂与欧洲合作','欧洲如何处理共同历史？','城市重建、冷战与欧洲一体化塑造战后生活。欧盟是部分欧洲国家的合作制度，不能等同整个欧洲，也不是古代帝国的重现。','把保存、重建与记忆作为继续理解当代欧洲的入口。']
].map(([id,date,title,question,summary,next])=>({id,date,title,question,summary,next}));
